function run(input) {
    try {
        const data = typeof input === "string"
            ? JSON.parse(input)
            : input;

        if (
            !data ||
            !data.records ||
            !Array.isArray(data.records) ||
            data.records.length === 0
        ) {
            return JSON.stringify({
                error: true,
                message: "Nenhum contato encontrado"
            });
        }

        const record = data.records[0];

        function formatarNome(valor) {
            if (!valor || typeof valor !== "string") {
                return "";
            }

            return valor
                .trim()
                .toLowerCase()
                .split(/\s+/)
                .map(function (palavra) {
                    return palavra.charAt(0).toUpperCase() + palavra.slice(1);
                })
                .join(" ");
        }

        return JSON.stringify({
            Id: record.Id || "",
            AccountId: record.AccountId || "",
            FirstName: formatarNome(record.FirstName),
            Name: formatarNome(record.Name),
            Email: record.Email || "",
            OwnerId: record.OwnerId || "",
            Status__c: record.Status__c || "",
            OptInEmail__c: record.OptInEmail__c === true,
            OptInSms__c: record.OptInSms__c === true
        });

    } catch (e) {
        return JSON.stringify({
            error: true,
            message: "Erro ao processar resposta",
            details: e.message
        });
    }
}

