function run(input) {
    try {
        const data = typeof input === "string"
            ? JSON.parse(input)
            : input;

        if (
            !data ||
            !data.records ||
            !Array.isArray(data.records) ||
            data.records.length === 0
        ) {
            return JSON.stringify({
                quantidade: 0,
                CaseNumber: "",
                CreatedDate: ""
            });
        }

        const records = data.records;

        function calcularTempo(createdDate) {
            if (!createdDate) {
                return "";
            }

            const dataCriacao = new Date(createdDate);
            const agora = new Date();

            const diferencaMs = agora.getTime() - dataCriacao.getTime();

            if (diferencaMs < 0) {
                return "";
            }

            const horas = diferencaMs / (1000 * 60 * 60);

            if (horas < 24) {
                return "há menos de um dia";
            }

            const dias = Math.floor(horas / 24);

            if (dias === 1) {
                return "há um dia";
            }

            return "há " + dias + " dias";
        }

        // Pega os CaseNumbers
        const caseNumbers = records
            .map(function (record) {
                return record.CaseNumber || "";
            })
            .filter(function (valor) {
                return valor !== "";
            });

        // Busca a data mais antiga
        let dataMaisAntiga = null;

        records.forEach(function (record) {
            if (!record.CreatedDate) {
                return;
            }

            const dataAtual = new Date(record.CreatedDate);

            if (
                !dataMaisAntiga ||
                dataAtual.getTime() < dataMaisAntiga.getTime()
            ) {
                dataMaisAntiga = dataAtual;
            }
        });

        const tempoMaisAntigo = dataMaisAntiga
            ? calcularTempo(dataMaisAntiga)
            : "";

        return JSON.stringify({
            quantidade: caseNumbers.length,
            CaseNumber: caseNumbers.join(", "),
            CreatedDate: tempoMaisAntigo
        });

    } catch (e) {
        return JSON.stringify({
            error: true,
            message: "Erro ao processar resposta",
            details: e.message
        });
    }
}

